style.css:
@-moz-document domain("photos.google.com") {
/* fundo mais rosinha */
body {
    background-color: #ffeef2 !important;
}

/* overlay rosa mais visível */
body::before {
    content: "";
    position: fixed;
    inset: 0;
    background: rgba(255, 182, 193, 0.12);
    pointer-events: none;
    z-index: 0;
}

/* mantém fotos normais */
img {
    position: relative;
    z-index: 1;
}

/* cards */
div[role="main"] > div {
    background-color: rgba(255, 255, 255, 0.6);
    border-radius: 12px;
}

/* hover bonitinho */
div:hover {
    background-color: rgba(255, 182, 193, 0.15);
}
}
